declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    Demand : BOOL;
    FaultA : BOOL;
    FaultB : BOOL;
END_VAR
VAR_OUTPUT
    PumpA : BOOL;
    PumpB : BOOL;
    LeadA : BOOL := TRUE;
END_VAR
VAR
PreferredA : BOOL := TRUE;
    PreviousDemand : BOOL := FALSE;
    Served : BOOL := FALSE;
END_VAR

implementation:
PumpA := FALSE; PumpB := FALSE;
IF NOT Demand THEN
    IF PreviousDemand AND Served THEN PreferredA := NOT PreferredA; END_IF;
    Served := FALSE;
ELSE
    IF NOT PreviousDemand THEN Served := FALSE; END_IF;
    IF PreferredA THEN
        PumpA := NOT FaultA;
        PumpB := FaultA AND NOT FaultB;
    ELSE
        PumpB := NOT FaultB;
        PumpA := FaultB AND NOT FaultA;
    END_IF;
    Served := Served OR PumpA OR PumpB;
END_IF;
PreviousDemand := Demand;
LeadA := PreferredA;
